import{c as a,Q as l,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E9%BB%98%E8%AE%A4MIX%E6%A8%A1%E5%BC%8F%E7%9A%84Matmul%E6%B5%81%E7%A8%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.CIdKr5UW.png",i="/assets/zh-cn_image_0000002411013306.vsQA1174.png",p="/assets/zh-cn_image_0000002390760922.wlQUKrjl.png",o="/assets/%E7%BA%AFCube%E6%A8%A1%E5%BC%8F%E7%9A%84Matmul%E6%B5%81%E7%A8%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.Bl9R_dbb.png",u="/assets/zh-cn_image_0000002411013940.BqS8pjRF.png",c="/assets/zh-cn_image_0000002377887318.tonbghbP.png",A=JSON.parse('{"title":"Matmul高阶API使能纯Cube模式","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能纯Cube模式","slug":"matmul高阶api使能纯cube模式"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能纯Cube模式.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能纯Cube模式.md"}'),r={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能纯Cube模式.md"};function g(d,t,m,h,b,_){return l(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="matmul高阶api使能纯cube模式" tabindex="-1">Matmul高阶API使能纯Cube模式 <a class="header-anchor" href="#matmul高阶api使能纯cube模式" aria-label="Permalink to &quot;Matmul高阶API使能纯Cube模式&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在矩阵乘算子场景中，使能Matmul高阶API的纯Cube模式对算子性能的提升效果。如下图所示，Matmul API默认使用MIX模式，即用户从AIV侧发起消息，通过消息通信框架中转消息后，在AIC侧执行Matmul计算。这套消息处理机制会带来额外的Scalar性能开销。相较于MIX模式，纯Cube模式可以直接跳过消息通信框架，完成Matmul计算，提升算子性能。</p><p><strong>图 1</strong> 默认MIX模式的Matmul流程示意图<br><img src="'+n+'" alt="" title="默认MIX模式的Matmul流程示意图"></p><ul><li><p>使能纯Cube模式的适用场景</p><p>非融合算子，只有矩阵计算的场景。即相较于MIX模式（包含矩阵计算和矢量计算），没有矢量计算的场景。本案例的算子规格如下：</p></li></ul><p><strong>表 1</strong> 算子用例规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;128, 64&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;64, 30720&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共24个核，每个核中包含1个AIC核和2个AIV核。</p><p>Tiling参数如下：</p><ul><li><p>原始shape：M=128, N=30720, K=64。</p></li><li><p>单核shape：</p><ul><li>MIX场景：按48个AIV核进行切分，singleCoreM=128，singleCoreN=640，singleCoreK=64。</li><li>纯Cube场景：按24个AIC核进行切分，singleCoreM=128，singleCoreN=1280，singleCoreK=64。</li></ul></li><li><p>基本块shape：baseM=128，baseN=256，baseK=64。</p></li><li><p>L1相关Tiling参数：stepM=1，stepN=1，stepKa=4，stepKb=4，depthA1=8，depthB1=8。</p></li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据。因为纯Cube模式主要优化Scalar流水性能，可以重点分析Scalar的流水情况。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li><p>优化前的Profiling数据如下，从C列的aic_time数据可以看出，多个核中最大算子执行耗时为17.85us。从G列的aic_scalar_time数据可以看出，Scalar平均耗时为15.02us，性能瓶颈在Scalar流水。</p><p><img src="'+i+'" alt=""></p></li><li><p>优化前的流水图如下，由于默认为MIX模式，每次Matmul计算均涉及消息通信框架对消息进行处理，Scalar流水重，性能开销较大，如下图红框所示。</p><p><img src="'+p+`" alt=""></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>默认MIX模式下，用户在AIV侧发起消息，通过消息通信框架中转消息后，在AIC侧执行Matmul计算。基于这样的流程，用户使用Matmul高阶API编写算子代码时，可以使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/REGIST_MATMUL_OBJ.md" target="_blank" rel="noreferrer">REGIST_MATMUL_OBJ</a>宏，无需区分AIV和AIC，但也因这套消息处理机制导致产生了额外的性能开销，如<a href="#fig0672118378">图1 默认MIX模式的Matmul流程示意图</a>所示。</p><p>实现默认MIX模式的具体步骤如下：</p><ol><li><p>Kernel侧，定义Matmul对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, AType&gt;;</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BType&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE =  AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_NORM&gt; matmulObj;</span></span></code></pre></div></li><li><p>Host侧，Matmul多核Tiling对象调用SetDim接口设置参与运算的核数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();</span></span>
<span class="line"><span>matmul_tiling::MultiCoreMatmulTiling cubeTiling(*ascendcPlatform);</span></span>
<span class="line"><span>int32_t numBlocks = ascendcPlatform-&gt;GetCoreNumAiv(); // MIX模式使用GetCoreNumAiv获取AI处理器可用的核数。</span></span>
<span class="line"><span>cubeTiling.SetDim(numBlocks);</span></span></code></pre></div></li><li><p>调用核函数，参考<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html#zh-cn_topic_0000001447989210_section1915102519220">核函数定义和调用</a>，设置核函数的numBlocks参数配置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>matmul_custom_do(ascendcPlatform-&gt;GetCoreNumAic(), stream, x1, x2, bias, y, workspaceDevice, tilingDevice); // MIX模式下，启动时，按照AIV和AIC组合启动，numBlocks用于设置启动多少个AI Core。</span></span></code></pre></div></li></ol><p>在没有矢量计算的算子场景下，可以跳过消息通信框架的机制，使能纯Cube模式完成Matmul计算，减少消息通信的性能开销，提升算子性能。</p><p><strong>图 2</strong> 纯Cube模式的Matmul流程示意图<br><img src="`+o+`" alt="" title="纯Cube模式的Matmul流程示意图"></p><p>Matmul API使能纯Cube模式的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul" target="_blank" rel="noreferrer">纯Cube模式的Matmul样例</a>。使能纯Cube模式的主要步骤如下：</p><ol><li><p>Kernel侧，在定义Matmul对象的代码中，包含matmul_intf.h头文件前设置ASCENDC_CUBE_ONLY宏。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ASCENDC_CUBE_ONLY</span><span> // 在#include &quot;lib/matmul_intf.h&quot;前，设置ASCENDC_CUBE_ONLY宏</span></span>
<span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, AType&gt;;</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BType&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE =  AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_NORM&gt; matmulObj;</span></span></code></pre></div></li><li><p>Host侧，Matmul多核Tiling对象调用SetDim接口设置参与运算的核数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();</span></span>
<span class="line"><span>matmul_tiling::MultiCoreMatmulTiling cubeTiling(*ascendcPlatform);</span></span>
<span class="line"><span>int32_t numBlocks = ascendcPlatform-&gt;GetCoreNumAic(); // 纯Cube模式使用GetCoreNumAic接口获取AI处理器可用的核数。</span></span>
<span class="line"><span>cubeTiling.SetDim(numBlocks);</span></span></code></pre></div></li><li><p>调用核函数，参考<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html#zh-cn_topic_0000001447989210_section1915102519220">核函数定义和调用</a>，设置核函数的numBlocks参数配置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>matmul_custom_do(ascendcPlatform-&gt;GetCoreNumAic(), stream, x1, x2, bias, y, workspaceDevice, tilingDevice); // 仅包含Cube计算的算子，numBlocks用于设置启动多少个AIC。</span></span></code></pre></div></li><li><p>Kernel侧，核函数实现中增加AIV侧返回分支。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void matmul_custom(GM_ADDR a, GM_ADDR b,</span></span>
<span class="line"><span>    GM_ADDR bias, GM_ADDR c, GM_ADDR workspace, GM_ADDR tilingGm)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    if (g_coreType == AscendC::AIV) { // 纯Cube模式，AIV侧直接return</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    // 其他代码</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>优化后的Profiling数据如下，从C列的aic_time数据来看，多个核中最大算子执行耗时为11.21us，较优化前的17.85us有较大提升。从G列的aic_scalar_time数据来看，Scalar平均耗时从优化前的15.02us降低至5.17us。</p><p><img src="`+u+'" alt=""></p></li><li><p>优化后的流水图如下。对比优化前的流水图，红框所示位置的Scalar流水明显变稀疏。纯Cube模式相较于MIX模式，减少了对消息通信的处理，优化了整体Scalar性能开销。</p><p><img src="'+c+'" alt=""></p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在只有矩阵计算，没有矢量计算的场景下，可以考虑使能纯Cube模式，优化Matmul计算中的消息通信性能开销，提升算子性能。</p>',26)])])}const q=a(r,[["render",g]]);export{A as __pageData,q as default};
